/* Thai Solitude homepage service illustration frames: 6:5 */
body.home .wp-block-uagb-container.uagb-block-db0b5e62 > figure.wp-block-image,
body.home .wp-block-uagb-container.uagb-block-9d58695e > figure.wp-block-image,
body.home .wp-block-uagb-container.uagb-block-bb505ec2 > figure.wp-block-image {
    width: 100%;
    margin: 0;
    overflow: hidden;
    border-radius: 16px;
}

body.home .wp-block-uagb-container.uagb-block-db0b5e62 > figure.wp-block-image img,
body.home .wp-block-uagb-container.uagb-block-9d58695e > figure.wp-block-image img,
body.home .wp-block-uagb-container.uagb-block-bb505ec2 > figure.wp-block-image img {
    display: block;
    width: 100%;
    height: auto;
    aspect-ratio: 6 / 5;
    object-fit: cover;
}

/* TS WORK WITH ME START */
.ts-wwm{--ts-green:var(--ast-global-color-0,#377a00);--ts-deep:var(--ast-global-color-3,#012104);--ts-pale:var(--ast-global-color-4,#eaf7eb);--ts-line:var(--ast-global-color-6,#d0ebcf);color:var(--ts-deep);margin:0 auto;max-width:1180px}
.ts-wwm>div{box-sizing:border-box}
.ts-wwm h1,.ts-wwm h2,.ts-wwm h3{color:#151716;line-height:1.12}
.ts-wwm h1{font-size:clamp(3.4rem,6vw,5.8rem);letter-spacing:-.055em;margin:.12em 0 .18em}
.ts-wwm h2{font-size:clamp(2rem,3.7vw,3.3rem);letter-spacing:-.035em;max-width:840px;margin:.15em 0 .55em}
.ts-wwm h3{font-size:1.35rem;margin:.35em 0 .55em}
.ts-wwm p{line-height:1.65}
.ts-wwm .ts-wwm__eyebrow{font-size:.78rem;font-weight:700;letter-spacing:.16em;line-height:1.4;text-transform:uppercase;color:var(--ts-green);margin-bottom:1.1rem}
.ts-wwm p a:not(.wp-block-button__link),.ts-wwm .ts-wwm__credential-list a{color:var(--ts-green);text-decoration:underline;text-underline-offset:.16em}
.ts-wwm p a:not(.wp-block-button__link):hover,.ts-wwm p a:not(.wp-block-button__link):focus-visible,.ts-wwm .ts-wwm__credential-list a:hover,.ts-wwm .ts-wwm__credential-list a:focus-visible{color:var(--ts-deep)}
.ts-wwm .ts-wwm__hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) minmax(230px,.55fr);align-items:center;gap:clamp(1.5rem,4vw,4rem);min-height:470px;padding:clamp(3rem,6vw,5.5rem) clamp(1.5rem,6vw,5.5rem);background:var(--ts-pale);border-radius:22px}
.ts-wwm .ts-wwm__hero:after{content:"";position:absolute;width:39%;aspect-ratio:1;right:-8%;top:6%;border:2px solid var(--ts-line);border-radius:48% 52% 56% 44%;transform:rotate(-26deg);box-shadow:-28px 30px 0 -10px #dff1df,-58px 60px 0 -20px #cfe8cc;pointer-events:none}
.ts-wwm .ts-wwm__hero>*{position:relative;z-index:1}
.ts-wwm .ts-wwm__hero-photo{margin:0;align-self:stretch;max-height:430px;min-height:320px}
.ts-wwm .ts-wwm__hero-photo img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 24%;border-radius:16px}
.ts-wwm .ts-wwm__identity{font-size:1rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--ts-green);margin:0 0 1rem}
.ts-wwm .ts-wwm__lead{font-size:clamp(1.15rem,1.8vw,1.35rem);line-height:1.55;max-width:650px;margin:0}
.ts-wwm .ts-wwm__experience{font-size:.93rem;font-weight:700;margin:1.3rem 0 0}
.ts-wwm .ts-wwm__hero-links{font-size:.88rem;margin:1rem 0 0}
.ts-wwm .wp-block-buttons{gap:.8rem;margin-top:1.8rem}
.ts-wwm .wp-block-button__link{border-radius:10px;padding:.8em 1.4em;text-decoration:none}
.ts-wwm .wp-block-button__link:focus-visible,.ts-wwm a:focus-visible{outline:3px solid var(--ts-deep);outline-offset:3px}
.ts-wwm .ts-wwm__intro,.ts-wwm .ts-wwm__approach,.ts-wwm .ts-wwm__owners,.ts-wwm .ts-wwm__credentials,.ts-wwm .ts-wwm__invitation,.ts-wwm .ts-wwm__clients{padding:clamp(3.2rem,7vw,6rem) clamp(1.5rem,6vw,5.5rem)}
.ts-wwm .ts-wwm__intro{max-width:900px;margin:auto;text-align:center}
.ts-wwm .ts-wwm__intro h2{margin-left:auto;margin-right:auto}
.ts-wwm .ts-wwm__intro p:not(.ts-wwm__eyebrow){font-size:1.08rem}
.ts-wwm .ts-wwm__approach{text-align:center;background:#f7fbf7;border-radius:22px}
.ts-wwm .ts-wwm__approach h2,.ts-wwm .ts-wwm__section-lead{margin-left:auto;margin-right:auto}
.ts-wwm .ts-wwm__section-lead{font-size:1.08rem;max-width:760px}
.ts-wwm .ts-wwm__cards{gap:1rem;margin-top:2rem;text-align:left}
.ts-wwm .ts-wwm__cards>.wp-block-column{background:#fff;border:1px solid var(--ts-line);border-radius:16px;padding:1.7rem}
.ts-wwm .ts-wwm__number{font-size:.82rem;font-weight:700;color:var(--ts-green);letter-spacing:.12em;margin-bottom:1.25rem}
.ts-wwm .ts-wwm__owners-grid{gap:1rem;margin:2rem 0 0}
.ts-wwm .ts-wwm__owners,.ts-wwm .ts-wwm__credentials,.ts-wwm .ts-wwm__clients{scroll-margin-top:90px}
.ts-wwm .ts-wwm__owners-grid>.wp-block-column{border-top:3px solid var(--ts-green);background:var(--ts-pale);padding:1.7rem;border-radius:0 0 14px 14px}
.ts-wwm .ts-wwm__credentials{background:#f7fbf7;border-radius:22px}
.ts-wwm .ts-wwm__credential-list{list-style:none;padding:0;margin:1.8rem 0 0;max-width:800px}
.ts-wwm .ts-wwm__credential-list li{border-top:1px solid var(--ts-line);padding:.85rem 0;line-height:1.55;font-size:1.05rem}
.ts-wwm .ts-wwm__credential-list li:last-child{border-bottom:1px solid var(--ts-line)}
.ts-wwm .ts-wwm__invitation{background:var(--ts-pale);border-radius:22px;margin:2rem 0}
.ts-wwm .ts-wwm__invitation p:not(.ts-wwm__eyebrow){max-width:730px;font-size:1.08rem}
.ts-wwm .ts-wwm__invitation .ts-wwm__email{font-size:.93rem;margin-top:1.4rem}
.ts-wwm .ts-wwm__clients{background:#f7fbf7;border-radius:22px;margin-bottom:4rem}
.ts-wwm .ts-wwm__clients p:not(.ts-wwm__eyebrow){max-width:800px;font-size:1.08rem}
.ts-wwm .is-style-outline .wp-block-button__link{color:var(--ts-green);border-color:var(--ts-green);background:transparent}
